select id, session_id, event_type, page, event_time, duration_sec, percent_rank() over (partition by session_id order by duration_sec desc nulls last) as duration_sec_percent_rank, sum(duration_sec) over (partition by session_id order by duration_sec, id rows between unbounded preceding and current row) as cumulative_duration_sec, ntile(5) over (partition by event_type order by duration_sec, id) as duration_sec_bucket from web_events;
